with cleaned as (select id, device_code, reading_ts, temp_c, humidity, status_bits, firmware, cast(status_bits as string) as status_bits_num, length(firmware) as firmware_length from device_readings where hour(reading_ts) between 12 and 16), with_gaps as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval 45 minutes then 1 else 0 end as new_group_flag from cleaned), sessions_device_readings as (select id, device_code, reading_ts, humidity, status_bits, firmware, sum(new_group_flag) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as island_id from with_gaps) select date_trunc('day', reading_ts) as activity_day, approx_percentile(island_id, 0.95) as island_id_p95, stddev_samp(status_bits) as status_bits_stddev, sort_array(collect_set(device_code)) as device_code_list, max(island_id) filter (where device_code = 'DV-03') as dv_03_max_island_id, corr(humidity, status_bits) as corr_humidity_status_bits, sum(humidity) filter (where device_code = 'DV-02') as dv_02_total_humidity from sessions_device_readings group by date_trunc('day', reading_ts) having island_id_p95 < 1000000 order by island_id_p95 nulls first;
